#include "dfre/mission_netsock_periodic.hpp"
#include "dfre/mission_netsock_host_setup.hpp"
#include "dfre/mission_netsock_dispatch.hpp"
#include "dfre/mission_netsock_outgoing.hpp"
#include <stdexcept>
namespace dfre {namespace {using U=std::uint32_t;
U read(const MissionNetsockPeriodicBindings& b,U at,U n=4){if(!b.read)throw std::runtime_error("Netsock periodic current read is not bound");return b.read(at,n);}
void write(const MissionNetsockPeriodicBindings& b,U at,U value,U n=4){if(!b.write)throw std::runtime_error("Netsock periodic current store is not bound");b.write(at,n,value);}
std::int64_t si(U x){return x<=0x7fffffffu?x:std::int64_t(x)-0x100000000ll;}
struct Frame{const MissionNetsockPeriodicBindings& b;U site,size,at;Frame(const MissionNetsockPeriodicBindings& v,U s,U n,const std::vector<U>& a):b(v),site(s),size(n),at(0){if(!b.frame||!b.release)throw std::runtime_error("Netsock periodic frame is not bound");at=b.frame(site,size,a);}~Frame(){b.release(site,at,size);}};
U foreign(const MissionNetsockPeriodicBindings& b,U target,const std::vector<U>& args){if(b.before_call)b.before_call(target,args);if(!b.call)throw std::runtime_error("Netsock periodic required OS, log or thread service is not bound");return b.call(target,args);}
U body(const MissionNetsockPeriodicBindings& b,U target,const std::vector<U>& args){if(b.before_call)b.before_call(target,args);switch(target){case 0x10001830:mission_netsock_client_close(b);return 0;case 0x100017f0:mission_netsock_host_close(b);return 0;case 0x10003e20:mission_netsock_host_close_notices(b);return 0;case 0x10003e90:mission_netsock_remove_players(b);return 0;case 0x100025a0:return mission_netsock_usage_grow(b);default:break;}U n=8;switch(target){case 0x10002b80:n=0x68;break;case 0x100042e0:n=0x14;break;case 0x10002620:n=0x48;break;case 0x10004220:case 0x10005240:n=0x14;break;default:break;}Frame f(b,target,n,args);switch(target){case 0x10002d30:mission_netsock_connection_usage(b,f.at);return 0;case 0x10002b80:mission_netsock_player_usage(b,f.at);return 0;case 0x10004820:mission_netsock_address_expire(b,f.at);return 0;case 0x10004600:mission_netsock_address_remove(b,f.at);return 0;case 0x10004490:mission_netsock_player_remove(b,f.at);return 0;case 0x100042e0:mission_netsock_player_log(b,f.at);return 0;case 0x10005010:return mission_netsock_ip_text(b,f.at);case 0x10002620:mission_netsock_usage_send(b,f.at);return 0;case 0x10004220:mission_netsock_receive_enqueue(b,f.at);return 0;case 0x10005240:return mission_netsock_send_direct(b,f.at);default:throw std::runtime_error("Netsock periodic source body is not bound");}}
void zero(const MissionNetsockPeriodicBindings& b,U at,U dwords){for(U i=0;i<dwords;++i)write(b,at+i*4,0);}
void record_zero(const MissionNetsockPeriodicBindings& b,U at){zero(b,at,0x12);write(b,at+0x48,0,2);}
void record_copy(const MissionNetsockPeriodicBindings& b,U to,U from){for(U i=0;i<0x12;++i){const auto v=read(b,from+i*4);write(b,to+i*4,v);}const auto tail=read(b,from+0x48,2);write(b,to+0x48,tail,2);}
}
void mission_netsock_periodic(const MissionNetsockPeriodicBindings& b){const auto first_count=read(b,0x100198b8);auto address=read(b,0x10019af8);auto player=read(b,0x10019afc);if(!first_count)return;for(U i=0;;++i,address+=0x18,player+=0xbc){if(read(b,address)&&read(b,address+4)!=0xffffffffu){const U age=read(b,address+8)+1u;write(b,address+8,age);if(age>120){body(b,0x10002d30,{address});body(b,0x10004820,{address});}}if(read(b,player+0x9c)&&read(b,player+0x98)){const U age=read(b,player+0xac)+1u;write(b,player+0xac,age);if(age>300)body(b,0x10002b80,{player,1});}const auto count=read(b,0x100198b8);if(i+1u>=count)break;}}
void mission_netsock_connection_usage(const MissionNetsockPeriodicBindings& b,U frame){const auto initial=read(b,0x100198b8);auto player=read(b,0x10019afc);if(!initial)return;const auto address=read(b,frame+4);for(U i=0;;++i,player+=0xbc){if(read(b,player+0xa4)==address){const auto player_age=read(b,player+0xac),address_age=read(b,address+8);write(b,player+0xac,player_age>address_age?player_age-address_age:0);body(b,0x10002b80,{player,3});}const auto count=read(b,0x100198b8);if(i+1u>=count)break;}}
void mission_netsock_player_usage(const MissionNetsockPeriodicBindings& b,U frame){auto row=read(b,0x10007698);if(!row)return;const auto player=read(b,frame+0x60);if(!player||!read(b,player+0x9c)||!read(b,player+0x98))return;const auto initial_count=read(b,0x1000769c);write(b,frame+0x60,0);bool found=false;if(si(initial_count)>0){for(U i=0;;++i,row+=0x4a){if(read(b,row+0x12,2)){bool equal=true;for(U j=0;j<4;++j){const auto right=read(b,player+0x88+j*4),left=read(b,row+j*4);if(left!=right){equal=false;break;}}if(equal){found=true;break;}}const auto count=read(b,0x1000769c);if(si(i+1u)>=si(count))break;}}
 if(found)write(b,frame+0x60,1);else row=body(b,0x100025a0,{});if(row){const auto saved=read(b,frame+0x60);if(saved)record_copy(b,frame+0x10,row);else record_zero(b,frame+0x10);record_zero(b,row);write(b,row+0x12,1,2);for(U i=0;i<4;++i){const auto key=read(b,player+0x88+i*4);if(i==3)write(b,row+0x10,1,2);write(b,row+i*4,key);}const auto clock=read(b,0x10006088),now=foreign(b,clock,{});write(b,row+0x18,now);for(U i=0;i<4;++i){const auto app=read(b,0x10007050+i*4);write(b,row+0x20+i*4,app);}const auto age=read(b,player+0xac,2);write(b,row+0x30,age,2);const auto other=read(b,player+0xb0,2);write(b,row+0x32,other,2);const auto address=read(b,player+0xa4);if(address){const auto ip=read(b,address+4);write(b,row+0x34,ip);}const auto reason=read(b,frame+0x64);if(reason==3){const auto flags=read(b,row+0x14,1);write(b,row+0x14,flags|1u,1);}else if(reason==2){const auto flags=read(b,row+0x14,1);write(b,row+0x14,flags|0x10u,1);}const auto total=read(b,player+0xb8,2),prior_age=read(b,frame+0x40,2),current_age=read(b,row+0x30,2);write(b,row+0x30,current_age+prior_age,2);const auto prior_other=read(b,frame+0x42,2),prior_total=read(b,frame+0x56,2),current_other=read(b,row+0x32,2);write(b,row+0x32,current_other+prior_other,2);write(b,row+0x46,total,2);const auto prior_flags=read(b,frame+0x24,2),flags=read(b,row+0x14,2);write(b,row+0x14,flags|prior_flags,2);const auto current_total=read(b,row+0x46,2);write(b,row+0x46,current_total+prior_total,2);body(b,0x10002620,{row,0});}write(b,player+0xac,0);write(b,player+0xb0,0);write(b,player+0xb8,0);}
void mission_netsock_address_expire(const MissionNetsockPeriodicBindings& b,U frame){const auto address=read(b,frame+4);body(b,0x10004600,{address});}
void mission_netsock_address_remove(const MissionNetsockPeriodicBindings& b,U frame){const auto address=read(b,frame+4);zero(b,address,6);const auto first=read(b,0x100198b8);auto player=read(b,0x10019afc);if(!first)return;for(U i=0;;++i,player+=0xbc){if(read(b,player+0x9c)&&read(b,player+0xa4)==address)body(b,0x10004490,{player});const auto count=read(b,0x100198b8);if(i+1u>=count)break;}}
void mission_netsock_player_remove(const MissionNetsockPeriodicBindings& b,U frame){const auto packet=read(b,0x10019c5c),player=read(b,frame+4);write(b,packet,0x1051,2);write(b,packet+2,8,2);const auto id=read(b,player+0xa0);write(b,packet+4,id);body(b,0x10004220,{packet,8,0,1});if(read(b,0x10019c68)){const auto address=read(b,player+0xa4);const auto ip=address?read(b,address+4):0;body(b,0x100042e0,{player,ip});}const auto payload=read(b,player+0x80);if(payload){const auto release=read(b,0x10006068);foreign(b,release,{payload});}zero(b,player,0x2f);const U count=read(b,0x100198bc)-1u;write(b,0x100198bc,count);}
void mission_netsock_player_log(const MissionNetsockPeriodicBindings& b,U frame){const auto time=read(b,0x10006078);foreign(b,time,{frame+4});const auto local=read(b,0x1000607c),calendar=foreign(b,local,{frame+4});const auto format=read(b,0x1000603c),stamp=foreign(b,format,{calendar});const auto player=read(b,frame+0xc);const auto id=read(b,player+0xa0),ip=read(b,frame+0x10);const auto address=body(b,0x10005010,{ip});const auto file=read(b,0x10019c6c),print=read(b,0x10006070);foreign(b,print,{file,0x10007214,player,address,id,stamp});}
U mission_netsock_ip_text(const MissionNetsockPeriodicBindings& b,U frame){const auto ip=read(b,frame+4);return foreign(b,0x1000594c,{ip});}
void mission_netsock_ping_timer(const MissionNetsockPeriodicBindings& b,U frame){if(!read(b,0x10019c88))return;const auto started=read(b,0x10019c96),now=read(b,frame+0xc);if(now>started+10000u){const auto host=read(b,0x100198ac);write(b,0x10019c88,0);write(b,0x10019c8c,0x31);if(!host)body(b,0x10001830,{});return;}const auto last=read(b,0x10019c9a);if(now<=last+1500u)return;write(b,frame,0);write(b,0x10019c9a,now);write(b,frame+4,0);const auto ip=read(b,0x10019c92);write(b,frame+6,now,2);const auto port=read(b,0x10019c90,2);write(b,frame+2,now>>16,2);write(b,frame,0x1012,2);write(b,frame+4,0x14,2);body(b,0x10005240,{frame,8,ip,(now&0xffff0000u)|port});}
void mission_netsock_client_close(const MissionNetsockPeriodicBindings& b){const auto sleep=read(b,0x10006010);write(b,0x10019c14,0);write(b,0x10019c18,0x10000);write(b,0x10019c10,1);do{foreign(b,sleep,{10});}while(!read(b,0x10019c14));write(b,0x10019b40,1);write(b,0x100198ac,0);}
void mission_netsock_usage_free(const MissionNetsockPeriodicBindings& b){const auto pool=read(b,0x10007698);if(pool){const auto release=read(b,0x10006068);foreign(b,release,{pool});}write(b,0x10007698,0);}
U mission_netsock_close_session(const MissionNetsockPeriodicBindings& b){if(!read(b,0x10019880))return 1;if(!read(b,0x10019884))return 0x200;if(!read(b,0x100198ac))return 4;if(read(b,0x100199b0)==1)body(b,0x100017f0,{});else body(b,0x10001830,{});return 0;}
void mission_netsock_host_close(const MissionNetsockPeriodicBindings& b){body(b,0x10003e20,{});write(b,0x10019b08,1);body(b,0x10003e90,{});const auto players=read(b,0x10019afc),release=read(b,0x10006068);foreign(b,release,{players});const auto addresses=read(b,0x10019af8);foreign(b,release,{addresses});write(b,0x100198ac,0);}
void mission_netsock_host_close_notices(const MissionNetsockPeriodicBindings& b){const auto initial_packet=read(b,0x10019c5c);write(b,initial_packet,0x1052,2);write(b,initial_packet+2,4,2);const auto first=read(b,0x100198b8);auto player=read(b,0x10019afc);if(!first)return;for(U i=0;;++i,player+=0xbc){if(read(b,player+0x9c)&&read(b,player+0x98)){const auto address=read(b,player+0xa4);const auto port=read(b,address+0x14,2),ip=read(b,address+4),length=read(b,initial_packet+2,2),packet=read(b,0x10019c5c);body(b,0x10005240,{packet,length,ip,port});}const auto count=read(b,0x100198b8);if(i+1u>=count)break;}}
void mission_netsock_remove_players(const MissionNetsockPeriodicBindings& b){const auto first=read(b,0x100198b8);auto player=read(b,0x10019afc);if(!first)return;for(U i=0;;++i,player+=0xbc){if(read(b,player+0x9c))body(b,0x10004490,{player});const auto count=read(b,0x100198b8);if(i+1u>=count)break;}}
} // namespace dfre
